// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 newVal) public {
        vm.assume(newVal < type(uint256).max);

        // Before initialization, setting MinSum succeeds in both versions.
        bool ok0;
        try c.SetMinSum(newVal) { ok0 = true; } catch { ok0 = false; }
        assertTrue(ok0);

        // Freeze the configuration.
        c.Initialized();

        // Rule: after initialization, SetMinSum must always revert.
        bool ok;
        try c.SetMinSum(newVal + 1) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
